241|int mz_deflate(mz_streamp pStream, int flush)
242|{
243|    size_t in_bytes, out_bytes;
244|    mz_ulong orig_total_in, orig_total_out;
245|    int mz_status = MZ_OK;
246|
247|    if ((!pStream) || (!pStream->state) || (flush < 0) || (flush > MZ_FINISH) || (!pStream->next_out))
248|        return MZ_STREAM_ERROR;
249|    if (!pStream->avail_out)
250|        return MZ_BUF_ERROR;
251|
252|    if (flush == MZ_PARTIAL_FLUSH)
253|        flush = MZ_SYNC_FLUSH;
254|
255|    if (((tdefl_compressor *)pStream->state)->m_prev_return_status == TDEFL_STATUS_DONE)
256|        return (flush == MZ_FINISH) ? MZ_STREAM_END : MZ_BUF_ERROR;
257|
258|    orig_total_in = pStream->total_in;
259|    orig_total_out = pStream->total_out;
260|    for (;;)
261|    {
262|        tdefl_status defl_status;
263|        in_bytes = pStream->avail_in;
264|        out_bytes = pStream->avail_out;
265|
266|        defl_status = tdefl_compress((tdefl_compressor *)pStream->state, pStream->next_in, &in_bytes, pStream->next_out, &out_bytes, (tdefl_flush)flush);
267|        pStream->next_in += (mz_uint)in_bytes;
268|        pStream->avail_in -= (mz_uint)in_bytes;
269|        pStream->total_in += (mz_uint)in_bytes;
270|        pStream->adler = tdefl_get_adler32((tdefl_compressor *)pStream->state);
271|
272|        pStream->next_out += (mz_uint)out_bytes;
273|        pStream->avail_out -= (mz_uint)out_bytes;
274|        pStream->total_out += (mz_uint)out_bytes;
275|
276|        if (defl_status < 0)
277|        {
278|            mz_status = MZ_STREAM_ERROR;
279|            break;
280|        }
281|        else if (defl_status == TDEFL_STATUS_DONE)
282|        {
283|            mz_status = MZ_STREAM_END;
284|            break;
285|        }
286|        else if (!pStream->avail_out)
287|            break;
288|        else if ((!pStream->avail_in) && (flush != MZ_FINISH))
289|        {
290|            if ((flush) || (pStream->total_in != orig_total_in) || (pStream->total_out != orig_total_out))
291|                break;
292|            return MZ_BUF_ERROR; /* Can't make forward progress without some input.
293| */
294|        }
295|    }
296|    return mz_status;
297|}
