299|int mz_deflateEnd(mz_streamp pStream)
300|{
301|    if (!pStream)
302|        return MZ_STREAM_ERROR;
303|    if (pStream->state)
304|    {
305|        pStream->zfree(pStream->opaque, pStream->state);
306|        pStream->state = NULL;
307|    }
308|    return MZ_OK;
309|}
