318|int mz_compress2(unsigned char *pDest, mz_ulong *pDest_len, const unsigned char *pSource, mz_ulong source_len, int level)
319|{
320|    int status;
321|    mz_stream stream;
322|    memset(&stream, 0, sizeof(stream));
323|
324|    /* In case mz_ulong is 64-bits (argh I hate longs). */
325|    if ((mz_uint64)(source_len | *pDest_len) > 0xFFFFFFFFU)
326|        return MZ_PARAM_ERROR;
327|
328|    stream.next_in = pSource;
329|    stream.avail_in = (mz_uint32)source_len;
330|    stream.next_out = pDest;
331|    stream.avail_out = (mz_uint32)*pDest_len;
332|
333|    status = mz_deflateInit(&stream, level);
334|    if (status != MZ_OK)
335|        return status;
336|
337|    status = mz_deflate(&stream, MZ_FINISH);
338|    if (status != MZ_STREAM_END)
339|    {
340|        mz_deflateEnd(&stream);
341|        return (status == MZ_OK) ? MZ_BUF_ERROR : status;
342|    }
343|
344|    *pDest_len = stream.total_out;
345|    return mz_deflateEnd(&stream);
346|}
