550|int mz_inflateEnd(mz_streamp pStream)
551|{
552|    if (!pStream)
553|        return MZ_STREAM_ERROR;
554|    if (pStream->state)
555|    {
556|        pStream->zfree(pStream->opaque, pStream->state);
557|        pStream->state = NULL;
558|    }
559|    return MZ_OK;
