665|    tinfl_decompressor decomp;
666|    void *pBuf = NULL, *pNew_buf;
667|    size_t src_buf_ofs = 0, out_buf_capacity = 0;
668|    *pOut_len = 0;
669|    tinfl_init(&decomp);
670|    for (;;)
671|    {
672|        size_t src_buf_size = src_buf_len - src_buf_ofs, dst_buf_size = out_buf_capacity - *pOut_len, new_out_buf_capacity;
673|        tinfl_status status = tinfl_decompress(&decomp, (const mz_uint8 *)pSrc_buf + src_buf_ofs, &src_buf_size, (mz_uint8 *)pBuf, pBuf ? (mz_uint8 *)pBuf + *pOut_len : NULL, &dst_buf_size,
674|                                               (flags & ~TINFL_FLAG_HAS_MORE_INPUT) | TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF);
675|        if ((status < 0) || (status == TINFL_STATUS_NEEDS_MORE_INPUT))
676|        {
677|            MZ_FREE(pBuf);
678|            *pOut_len = 0;
679|            return NULL;
