681|        src_buf_ofs += src_buf_size;
682|        *pOut_len += dst_buf_size;
683|        if (status == TINFL_STATUS_DONE)
684|            break;
685|        new_out_buf_capacity = out_buf_capacity * 2;
686|        if (new_out_buf_capacity < 128)
