691|            MZ_FREE(pBuf);
692|            *pOut_len = 0;
693|            return NULL;
694|        }
695|        pBuf = pNew_buf;
696|        out_buf_capacity = new_out_buf_capacity;
697|    }
698|    return pBuf;
